+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold on those days, actual use from every consume movement on those
+ * days, and difference = actual - theoretical (3 decimals). Items where both
+ * are zero are left out.
+ */
+export function varianceReport(store, from, to) {
+  const theoretical = new Map();
+  const actual = new Map();
+  const add = (map, itemId, qty) => map.set(itemId, Math.round(((map.get(itemId) ?? 0) + qty) * 1000) / 1000);
+  for (const sale of store.data.sales ?? []) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    for (const line of sale.lines) for (const n of lineUse(store, line)) add(theoretical, n.itemId, n.qty);
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !batchItem.has(m.batchId)) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    add(actual, batchItem.get(m.batchId), m.qty);
+  }
+  const ids = [...new Set([...theoretical.keys(), ...actual.keys()])].sort((a, b) => a - b);
+  return ids
+    .map((itemId) => {
+      const item = getItem(store, itemId);
+      const t = theoretical.get(itemId) ?? 0;
+      const a = actual.get(itemId) ?? 0;
+      return { itemId, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: Math.round((a - t) * 1000) / 1000 };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
