+// Sales from the till. Each ticket is recorded once; every dish sold uses one
+// portion of its recipe per qty, consumed from stock with ref `sale:<ticket>`.
+// Booking a set of tickets is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been recorded. */
+export function isSold(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient quantities used by one sale line ({ dishId, qty }). */
+export function lineUse(store, line) {
+  const dish = getDish(store, line.dishId);
+  return scaled(getRecipe(store, dish.recipeId), line.qty);
+}
+
+/**
+ * Records tickets [{ ticket, soldAt, lines: [{ dishId, qty, where }] }] and
+ * consumes their ingredients. Stock is checked line by line first; when an
+ * item runs out, throws sale_not_enough_stock naming the line's `where` and
+ * nothing changes. Returns the recorded sales.
+ */
+export function sell(store, tickets) {
+  const left = new Map();
+  const perTicket = tickets.map((t) => {
+    const needs = new Map();
+    for (const line of t.lines) {
+      for (const n of lineUse(store, line)) {
+        if (!left.has(n.itemId)) left.set(n.itemId, round3(onHand(store, n.itemId)));
+        const remaining = round3(left.get(n.itemId) - n.qty);
+        if (remaining < 0) {
+          const item = getItem(store, n.itemId);
+          throw new AppError("sale_not_enough_stock", { where: line.where, item: item.name, available: left.get(n.itemId), unit: item.unit });
+        }
+        left.set(n.itemId, remaining);
+        needs.set(n.itemId, round3((needs.get(n.itemId) ?? 0) + n.qty));
+      }
+    }
+    return needs;
+  });
+  const before = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    return tickets.map((t, i) => {
+      for (const [itemId, qty] of perTicket[i]) if (qty > 0) consume(store, itemId, qty, { at: t.soldAt, ref: `sale:${t.ticket}` });
+      const sale = { id: store.nextId("sale"), ticket: t.ticket, soldAt: t.soldAt, lines: t.lines.map((l) => ({ dishId: l.dishId, qty: l.qty })) };
+      store.data.sales.push(sale);
+      return sale;
+    });
+  } catch (e) {
+    store.data = before;
+    throw e;
+  }
+}
